  function renderEvidenceRequestBanner(issue){
    let b=$('#civiclens-evidence-request-banner');
    if(!issue){
      b?.remove();
      return;
    }
    if(!b){
      b=document.createElement('div');
      b.id='civiclens-evidence-request-banner';
      const anchor=$('#recent-reports');
      anchor?.closest('section')?.insertAdjacentElement('beforebegin',b);
    }
    b.innerHTML=`<div><div style="font-weight:800;margin-bottom:4px">⚠️ Real photo requested</div><div style="font-size:14px;line-height:21px">An officer flagged the submitted image for review. Please upload a real photograph of <b>${esc(issue.title||'your reported issue')}</b>.</div></div><button type="button" id="civiclens-upload-real-photo">Upload Real Photo</button>`;
    b.className='civiclens-evidence-request-banner';
    $('#civiclens-upload-real-photo')?.addEventListener('click',()=>openEvidenceUpload(issue));
  }
  function openEvidenceUpload(issue){
    const existing=$('#civiclens-evidence-modal'); existing?.remove();
    const wrap=document.createElement('div');
    wrap.id='civiclens-evidence-modal';
    wrap.style.cssText='position:fixed;inset:0;background:rgba(35,26,0,.52);z-index:260;display:flex;align-items:center;justify-content:center;padding:18px';
    wrap.innerHTML=`<div style="background:#fff8f0;max-width:520px;width:100%;border-radius:20px;padding:26px;box-shadow:0 20px 60px rgba(0,0,0,.25)">
      <div style="display:flex;justify-content:space-between;gap:12px;align-items:start"><div><h3 style="margin:0;color:#450432;font:700 28px/34px 'Playfair Display',serif">Upload a Real Photo</h3><p style="margin:8px 0 18px;color:#51434a">Please photograph the actual reported issue. This replaces neither your original evidence nor the officer's resolution proof.</p></div><button type="button" id="close-evidence-modal" style="border:0;background:transparent;font-size:24px;cursor:pointer">×</button></div>
      <div style="background:#ffecbe;border:1px solid #d6c1c9;border-radius:12px;padding:12px;margin-bottom:16px;font-size:14px"><b>${esc(issue.tracking_id||'Report')}</b><br>${esc(issue.title||'Reported issue')}</div>
      <input id="civiclens-real-photo-input" type="file" accept="image/jpeg,image/png,image/webp,image/tiff,image/heic,image/heif" style="width:100%;padding:12px;border:1px dashed #9d3c5f;border-radius:12px;background:#fff"/>
      <img id="civiclens-real-photo-preview" alt="Real photo preview" style="display:none;width:100%;max-height:260px;object-fit:cover;border-radius:12px;margin-top:14px"/>
      <div style="display:flex;justify-content:flex-end;gap:10px;margin-top:20px"><button type="button" id="cancel-evidence-modal" class="civiclens-secondary">Cancel</button><button type="button" id="submit-real-photo" class="civiclens-primary">Send Photo to Officer</button></div>
    </div>`;
    document.body.appendChild(wrap);
    const input=$('#civiclens-real-photo-input'), preview=$('#civiclens-real-photo-preview');
    input?.addEventListener('change',()=>{const f=input.files?.[0];if(!f){preview.style.display='none';return}preview.src=URL.createObjectURL(f);preview.style.display='block'});
    const close=()=>wrap.remove();$('#close-evidence-modal')?.addEventListener('click',close);$('#cancel-evidence-modal')?.addEventListener('click',close);
    $('#submit-real-photo')?.addEventListener('click',async()=>{
      const f=input?.files?.[0]; if(!f)return notice('Choose a real photo first.','error');
      const btn=$('#submit-real-photo');btn.disabled=true;btn.textContent='Uploading…';
      try{
        const form=new FormData();form.append('image',f,f.name);
        await api(`/api/citizen/issues/${encodeURIComponent(issue.id)}/evidence`,{method:'POST',body:form});
        notice('Real photo sent to the municipal officer.');
        close();setTimeout(()=>location.reload(),500);
      }catch(e){btn.disabled=false;btn.textContent='Send Photo to Officer';notice(e.message,'error')}
    });
  }

