  async function wireAdminDashboard(){try{await requireRole('admin');const [d,m,rp]=await Promise.all([api('/api/admin/clusters'),api('/api/admin/metrics'),api('/api/admin/issues')]);setText('stat-open-issues',m.open_issues);setText('stat-overdue',m.overdue_count);const reports=$('#admin-reports-list');if(reports){const rows=rp.issues||[];reports.innerHTML=rows.map(i=>{const status=String(i.status||'reported').replace('_',' ');const priority=Number(i.cluster_priority||0);const tone=priority>=75?'High':priority>=50?'Medium':'Low';return `<article class="civiclens-admin-report"><div class="civiclens-admin-report-top"><div><b>${esc(i.title||i.category||'Citizen report')}</b><span class="civiclens-report-status">${esc(status)}</span></div><span class="civiclens-priority-${tone.toLowerCase()}">${tone} priority</span></div><p>${esc(i.description||'No description')}</p><div class="civiclens-admin-report-meta"><span>📍 ${esc(i.address||i.cluster_address||'Location selected')}</span><span>Ref: ${esc(i.tracking_id||'—')}</span><span>${dateLabel(i.created_at)}</span></div><button type="button" data-report-cluster="${esc(i.cluster_id||'')}">Open Cluster</button></article>`}).join('')||'<div class="civiclens-empty">No citizen reports yet. New submissions will appear here automatically.</div>';$$('[data-report-cluster]').forEach(b=>b.onclick=()=>b.dataset.reportCluster&&go(`cluster-detail.html?id=${encodeURIComponent(b.dataset.reportCluster)}`))}const el=$('#admin-map'),clusters=(d.clusters||[]).filter(c=>c.status!=='resolved'),openCluster=id=>go(`cluster-detail.html?id=${encodeURIComponent(id)}`);const render=()=>{if(!el)return;if(!window.L){mapFallback(el,clusters,openCluster);return}try{el.style.backgroundImage='none';el.innerHTML='';const map=L.map(el).setView([28.6139,77.209],14),tiles=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(map),bounds=[];let tileLoaded=false;tiles.on('tileload',()=>{tileLoaded=true});clusters.forEach(c=>{const lat=Number(c.lat),lng=Number(c.lng);if(!Number.isFinite(lat)||!Number.isFinite(lng))return;bounds.push([lat,lng]);const color=c.priority_score>=75?'#ba1a1a':c.priority_score>=50?'#f97316':'#16a34a';const icon=L.divIcon({className:'',html:`<div style="background:${color};width:20px;height:20px;border:3px solid white;border-radius:50%;box-shadow:0 1px 6px #333"></div>`,iconSize:[20,20],iconAnchor:[10,10]});const marker=L.marker([lat,lng],{icon}).addTo(map);marker.bindPopup(`<b>${esc(c.title||c.category||'Cluster')}</b>${c.escalated?' <span style="color:#ba1a1a;font-weight:700">⚠ Escalated</span>':''}<br>${esc(c.report_count||0)} reports · priority ${esc(c.priority_score)}${c.age_days!=null?` · ${esc(c.age_days)}d open`:''}<br>${esc(c.address||'')}<br><button data-open-cluster="${esc(c.id)}">Open Cluster</button>`);marker.on('popupopen',()=>setTimeout(()=>document.querySelector(`[data-open-cluster="${CSS.escape(c.id)}"]`)?.addEventListener('click',()=>openCluster(c.id)),0))});if(bounds.length)map.fitBounds(bounds,{padding:[40,40],maxZoom:15});setTimeout(()=>map.invalidateSize(),250);tiles.on('tileerror',()=>{if(!el.dataset.mapFallback){el.dataset.mapFallback='1';map.remove();mapFallback(el,clusters,openCluster)}});setTimeout(()=>{if(!tileLoaded&&!el.dataset.mapFallback){el.dataset.mapFallback='1';map.remove();mapFallback(el,clusters,openCluster)}},5000)}catch(e){mapFallback(el,clusters,openCluster)}};if(window.L)render();else{const s=document.createElement('script');s.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';s.onload=render;s.onerror=()=>mapFallback(el,clusters,openCluster);document.head.appendChild(s)}}catch(e){notice(e.message,'error')}}
  async function wireMetrics(){try{await requireRole('admin');const m=await api('/api/admin/metrics');setText('metric-fixed',`${m.outcomes.fixed}%`);setText('metric-pending',`${m.outcomes.pending}%`);setText('metric-reopened',`${m.outcomes.reopened}%`);setText('metric-resolution-hours',`${m.avg_resolution_hours}h`);setText('metric-recurrence',`${m.recurrence_rate}%`)}catch(e){notice(e.message,'error')}}
  async function wireEscalations(){try{await requireRole('admin');const p=await api('/api/admin/escalations');const main=$('main');if(main)main.innerHTML=`<section style="width:100%"><h1 style="font-size:32px;color:#450432;margin-bottom:18px">Escalations</h1><div class="grid grid-cols-1 md:grid-cols-2 gap-4">${(p.escalations||[]).map(x=>`<button data-eid="${esc(x.cluster_id||x.id)}" class="text-left bg-surface-container-lowest rounded-xl p-5 shadow-sm border-l-4 border-error"><b>${esc(x.title||x.issue)}</b><p>${esc(x.address||x.location)}</p><p>Priority: ${esc(x.priority_score||x.priority)} · Reports: ${esc(x.report_count||0)}</p><p>Status: ${esc(x.status)} · ${esc(x.reason||'Needs attention')}</p></button>`).join('')||'<p>No escalations right now.</p>'}</div></section>`;$$('[data-eid]').forEach(b=>b.onclick=()=>go(`cluster-detail.html?id=${encodeURIComponent(b.dataset.eid)}`))}catch(e){notice(e.message,'error')}}
  async function wireDetail(){try{await requireRole('admin');const id=new URLSearchParams(location.search).get('id');const p=await api(`/api/admin/clusters/${encodeURIComponent(id||'')}`),c=p.cluster||p;setText('cluster-title',c.title);setText('cluster-address',c.address);setText('cluster-count',c.report_count||c.affected_count);setText('cluster-priority',c.priority_score);setText('cluster-description',c.description||c.issues?.[0]?.description||'');
const evidence=$('#cluster-evidence');
if(evidence){
  const issues=p.issues||[];
  const reportImages=issues.flatMap(i=>(i.images||[]).filter(img=>['report','replacement','resolution'].includes(img.image_role)).map(img=>({...img,issueId:i.id,issueTitle:i.title||i.category||'Citizen report',trackingId:i.tracking_id||'',evidenceRequestStatus:i.evidence_request_status||'none'})));
  const escScore=v=>v===null||v===undefined||v===''?'—':`${Math.round(Number(v)*100)}%`;
  const detectorLabel=img=>{
    const provider=String(img.ai_detector_provider||'').toLowerCase();
    const status=String(img.ai_detector_status||'').toLowerCase();
    const state=String(img.final_authenticity_state||'').toLowerCase();
    const prob=img.ai_probability;
    if(state==='likely_synthetic'||status==='high_risk') return `<span class="civiclens-ai-badge civiclens-ai-risk">⚠ Possible AI-generated · ${escScore(prob)} probability</span>`;
    if(provider==='sightengine' && prob!==null && prob!==undefined) return `<span class="civiclens-ai-badge civiclens-ai-info">AI detector: ${escScore(prob)} probability</span>`;
    if(status==='uncertain'||state==='insufficient_evidence') return `<span class="civiclens-ai-badge civiclens-ai-muted">AI check inconclusive</span>`;
    return `<span class="civiclens-ai-badge civiclens-ai-muted">AI check: ${esc(status||'not run')}</span>`;
  };
  evidence.innerHTML=`<div class="flex items-start justify-between gap-4 mb-4"><div><h3 class="font-headline-md text-headline-md text-primary mb-1">Image Evidence &amp; Authenticity</h3><p class="font-body-md text-body-md text-on-surface-variant">Citizen-uploaded evidence and any available image-check results.</p></div><span class="font-label-sm text-label-sm text-on-surface-variant">${reportImages.length} image${reportImages.length===1?'':'s'}</span></div>`+
    (reportImages.length?`<div class="grid grid-cols-1 md:grid-cols-2 gap-4">${reportImages.map(img=>`<article class="rounded-xl bg-white border border-outline-variant/20 overflow-hidden"><div class="aspect-video bg-surface-container"><img src="${esc(img.url)}" alt="Citizen evidence" class="w-full h-full object-cover" loading="lazy" onerror="this.style.display='none';this.parentElement.innerHTML='<div class=\'h-full flex items-center justify-center text-sm text-on-surface-variant\'>Evidence preview unavailable</div>'"></div><div class="p-4"><div class="font-label-md text-label-md text-primary mb-2">${esc(img.issueTitle)}</div><div class="text-xs text-on-surface-variant mb-2">Ref: ${esc(img.trackingId||'—')} · SHA-256 stored</div>${detectorLabel(img)}${img.final_authenticity_state==='likely_synthetic'?'<p class="text-xs text-on-surface-variant mt-2">This is an advisory signal and should be manually reviewed; it is not proof that an image is fake.</p>':''}${img.image_role==='resolution'?`<div class="mt-3 rounded-lg bg-blue-50 border border-blue-200 px-3 py-2 text-xs font-semibold text-blue-900">🛠️ Authority resolution image attached; review source evidence and image-check results before relying on the claim.</div>`:(img.image_role==='replacement'?'<div class="mt-3 rounded-lg bg-green-50 border border-green-200 px-3 py-2 text-xs font-semibold text-green-800">Citizen follow-up photo received; image-check results are advisory.</div>':(img.final_authenticity_state==='likely_synthetic' && img.evidenceRequestStatus!=='submitted'?`<button type="button" class="civiclens-primary mt-4 w-full" data-request-real-photo="${esc(img.issueId)}">⚠ Request Real Photo from Citizen</button>`:''))}</div></article>`).join('')}</div>`:'<div class="rounded-lg bg-white p-4 text-sm text-on-surface-variant">No citizen evidence image is attached to the reports in this cluster yet.</div>');
}
  $$('[data-request-real-photo]').forEach(btn=>btn.addEventListener('click',async()=>{const issueId=btn.dataset.requestRealPhoto;if(!issueId)return;btn.disabled=true;btn.textContent='Sending request…';try{await api(`/api/admin/issues/${encodeURIComponent(issueId)}/request-real-photo`,{method:'POST'});notice('Request sent to the citizen. They will be asked to upload a real photo.');setTimeout(()=>location.reload(),500)}catch(e){btn.disabled=false;btn.textContent='⚠ Request Real Photo from Citizen';notice(e.message,'error')}}));
const input=$('#resolution-image'),preview=$('#resolution-preview'),status=$('#resolution-file-status'),remove=document.createElement('button');remove.textContent='Remove';remove.className='civiclens-secondary hidden';status?.after(remove);const picker=filePipeline(input,preview,status,remove);$('#resolution-camera-btn')?.addEventListener('click',async()=>{const f=await openCamera();if(f)picker.set(f)});const modalEl=$('#resolveModal'),open=()=>{if(modalEl){modalEl.classList.remove('hidden');modalEl.style.display='flex'}};$('#resolveBtn')?.addEventListener('click',open);$('#closeModalBtn')?.addEventListener('click',()=>modalEl?.classList.add('hidden'));$('#cancelModalBtn')?.addEventListener('click',()=>modalEl?.classList.add('hidden'));$('#submitResolutionBtn')?.addEventListener('click',async()=>{if(!picker.get())return notice('Choose a resolution photo.','error');const b=$('#submitResolutionBtn');b.disabled=true;try{const f=picker.get(),form=new FormData();form.append('image',f,f.name);form.append('resolution_note',$('#resolution-note')?.value||'Resolved by municipal maintenance team.');const result=await api(`/api/admin/clusters/${encodeURIComponent(id)}/resolution`,{method:'POST',body:form});const ai=result.ai_detector||{};const prob=ai.probability==null?'unavailable':`${Math.round(Number(ai.probability)*100)}%`;const flagged=String(result.final_authenticity_state||'').toLowerCase()==='likely_synthetic'||String(ai.status||'').toLowerCase()==='high_risk';const detectorReady=String(ai.provider||'').toLowerCase()==='sightengine'&&ai.probability!=null;const message=flagged?`Resolution photo attached. Image signal ${prob}; manual review is needed before relying on it.`:detectorReady?`Resolution photo attached. Sightengine returned ${prob} AI-generation probability. Citizen verification is pending.`:`Resolution photo attached. No external AI-detector result is available; citizen verification is pending.`;notice(message,flagged?'error':'success');setTimeout(()=>location.reload(),1200)}catch(e){b.disabled=false;notice(e.message,'error')}})}catch(e){notice(e.message,'error')}}
  async function wireDetailExtras(){const id=new URLSearchParams(location.search).get('id');if(!id)return;const reassign=$$('button').find(b=>/reassign crew/i.test(b.textContent));reassign?.addEventListener('click',async()=>{try{const p=await api('/api/admin/crews');const crews=p.crews||[];const body=crews.length?`<p>Select a municipal crew already recorded in the system.</p><label for="crew-select">Crew</label><select class="civiclens-field" id="crew-select">${crews.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} | ${esc(c.specialty||'General civic maintenance')} | ${esc(c.status)}</option>`).join('')}</select>`:`<p>No crew records exist yet. Add the real team name and specialty supplied by your municipality, then assign it to this cluster.</p><label for="crew-name">Municipal team name</label><input class="civiclens-field" id="crew-name" maxlength="120" placeholder="e.g. Ward 14 roads team"><label for="crew-specialty">Specialty</label><input class="civiclens-field" id="crew-specialty" maxlength="120" value="General civic maintenance">`;const m=modal(crews.length?'Reassign Crew':'Add and Assign Municipal Crew',body,`<button class="civiclens-primary" id="assign-crew">${crews.length?'Assign Crew':'Create and Assign'}</button>`);$('#assign-crew',m.root).onclick=async()=>{const button=$('#assign-crew',m.root);button.disabled=true;try{let crewId=$('#crew-select',m.root)?.value;if(!crews.length){const name=$('#crew-name',m.root).value.trim();if(!name)throw Error('Enter the municipal team name.');const created=await api('/api/admin/crews',{method:'POST',body:JSON.stringify({name,specialty:$('#crew-specialty',m.root).value.trim()})});crewId=created.crew.id}await api(`/api/admin/clusters/${encodeURIComponent(id)}/assign`,{method:'POST',body:JSON.stringify({crew_id:crewId})});notice('Crew assignment saved and reporters notified.');m.close();location.reload()}catch(e){button.disabled=false;notice(e.message,'error')}}}catch(e){notice(e.message,'error')}});const chat=$$('button').find(b=>/chat_bubble/i.test($('.material-symbols-outlined',b)?.textContent||''));chat?.addEventListener('click',async()=>{try{const p=await api(`/api/admin/clusters/${encodeURIComponent(id)}/comments`);const m=modal('Comments / Internal Notes',`<div id="comment-list">${(p.comments||[]).map(c=>`<p style="padding:8px;background:#fff2d8;border-radius:8px"><b>${esc(c.officer_name||c.author_name||'Officer')}</b> - ${dateLabel(c.created_at)}<br>${esc(c.body||c.comment)}</p>`).join('')||'<p>No comments yet.</p>'}<textarea class="civiclens-field" id="new-comment" placeholder="Add an internal note"></textarea><button class="civiclens-primary" id="add-comment">Add comment</button>`);$('#add-comment',m.root).onclick=async()=>{try{await api(`/api/admin/clusters/${encodeURIComponent(id)}/comments`,{method:'POST',body:JSON.stringify({body:$('#new-comment',m.root).value})});notice('Comment saved.');m.close()}catch(e){notice(e.message,'error')}}}catch(e){notice(e.message,'error')}})}
  async function wireVerifyFix(){try{await requireRole('citizen')}catch(e){return notice(e.message,'error')}const content=$('#verify-content'),empty=$('#verify-empty');try{const p=await api('/api/citizen/verify-target');const issue=p.issue;if(!issue){content?.classList.add('hidden');empty?.classList.remove('hidden');return}const images=issue.images||[];const before=images.find(i=>i.image_role==='report')||images[0];const after=images.find(i=>i.image_role==='resolution')||images[images.length-1];if(before)$('#beforeImage').src=before.url;if(after)$('#afterImage').src=after.url;setText('before-location',issue.address||'Reported location');setText('before-date',dateLabel(issue.created_at));setText('category-label',issue.category||'—');setText('resolution-note',issue.resolution_note||'Resolved by municipal maintenance team.');setText('resolution-time',dateLabel(issue.created_at));setText('verify-issue-title',`${issue.title||'Your report'} · Ref: ${issue.tracking_id||''}`);const respond=async approved=>{const approveBtn=$('#approve-btn'),rejectBtn=$('#reject-btn');approveBtn.disabled=true;rejectBtn.disabled=true;try{const r=await api(`/api/issues/${issue.id}/verify`,{method:'POST',body:JSON.stringify({approved})});notice(r.message||(approved?'Thanks for confirming!':'Issue reopened.'));setTimeout(()=>go('dashboard.html'),700)}catch(e){approveBtn.disabled=false;rejectBtn.disabled=false;notice(e.message,'error')}};$('#approve-btn').onclick=()=>respond(true);$('#reject-btn').onclick=()=>respond(false)}catch(e){notice(e.message,'error');content?.classList.add('hidden');empty?.classList.remove('hidden')}}
  async function wireSubmitted(){let data=null;try{data=JSON.parse(localStorage.getItem(LAST_SUBMISSION)||'null')}catch{}if(!data)return;const issue=data.issue||{};setText('tracking-id',`#${issue.tracking_id||'--'}`);const visualMatches=data.image_analysis?.similar_evidence_suggestions||[];setText('community-impact-note',(data.duplicate?`Grouped with ${Math.max(0,(data.cluster?.report_count||1)-1)} nearby report(s) to prioritize resolution.`:'A new civic issue cluster was created for this report.')+(visualMatches.length?` Similar image evidence may match ${visualMatches.length} earlier report(s); review these suggestions before linking.`:''));const summary=$('#image-authenticity-summary');const showAnalysis=analysis=>{if(!summary||!analysis)return;const state=analysis.final_authenticity_state||'insufficient_evidence';const labels={provenance_verified:'Verified provenance (C2PA signed)',needs_review:'Flagged for manual review',likely_synthetic:'Possible AI-generated image; flagged for review',insufficient_evidence:'Authenticity check inconclusive (informational only)'};summary.textContent=labels[state]||'Image authenticity check complete.'};showAnalysis(data.image_analysis);const panel=$('#photo-retry-panel');if(data.image_upload_pending&&panel){panel.classList.remove('hidden');const input=$('#retry-report-photo'),button=$('#retry-report-photo-btn'),status=$('#photo-retry-status');button?.addEventListener('click',async()=>{const file=input?.files?.[0];if(!file)return notice('Choose the report photo first.','error');button.disabled=true;if(status)status.textContent='Uploading photo...';try{const form=new FormData();form.append('image',file,file.name);const analysis=await api(`/api/issues/${encodeURIComponent(issue.id)}/images`,{method:'POST',body:form});data.image_analysis=analysis;data.image_upload_pending=false;localStorage.setItem(LAST_SUBMISSION,JSON.stringify(data));showAnalysis(analysis);panel.classList.add('hidden');notice('Photo attached to your saved report.')}catch(e){if(status)status.textContent=e.message;button.disabled=false}})}}

  document.addEventListener('DOMContentLoaded',()=>{addStyles();const p=location.pathname.toLowerCase();if(p.includes('/admin/')){if(p.endsWith('login.html'))wireAdminLogin();else{wireShell('admin');if(p.endsWith('dashboard.html'))wireAdminDashboard();else if(p.endsWith('metrics.html'))wireMetrics();else if(p.endsWith('escalations.html'))wireEscalations();else if(p.endsWith('cluster-detail.html')){wireDetail();wireDetailExtras()}}}else{if(p.endsWith('welcome.html')||p.endsWith('join.html'))wireAuth();if(p.endsWith('otp.html'))wireOtp();if(p.endsWith('report.html'))wireReport();if(p.endsWith('dashboard.html'))wireDashboard();if(p.endsWith('verify-fix.html'))wireVerifyFix();if(p.endsWith('submitted.html'))wireSubmitted();wireShell('citizen')}renderIcons()});
  window.CivicLens={api,openCamera,notice};
